def is_undulating(n):
    if n < 10:
        return False

    digits = [int(d) for d in str(abs(n))]

    prev_diff_sign = None
    for i in range(1, len(digits)):
        diff = digits[i] - digits[i-1]

        # If difference is zero or same sign as previous (excluding the first step which sets initial state), it's not undulating
        if diff == 0:
            return False

        current_sign = 1 if diff > 0 else -1

        if prev_diff_sign is None:
            prev_diff_sign = current_sign
        elif current_sign != -prev_diff_sign:
            pass # Correct alternation, continue
        else:
            return False

    return True

